    }
    function fillHidden() {
        var sels = document.querySelectorAll("select"), i;
        for (i = 0; i < sels.length; i++) {
            var s = sels[i];
            if (s.__eqilManaged && s.value === (s.__eqilPh || "") && s.__eqilDef && s.__eqilDef !== s.value && (s.disabled || !shown(s)) && hasValue(s, s.__eqilDef)) { s.value = s.__eqilDef; }
        }
        for (var n in groups) {
            var g = groups[n];
            if (g.managed && g.els && g.def !== null && g.def !== undefined && checkedValue(g.els) === null && !shown(g.els[0])) { setRadio(g.els, g.def); }
        }
    }
    function flag(els) {
        if (!styled) {
