                    for (var i = 0; i < names.length; i++) { if (typeof s[names[i]] === "string") { s[names[i]] = tr(s[names[i]]); } }
                    if (Array.isArray(s.insights)) {
                        for (var j = 0; j < s.insights.length; j++) {
                            var it = s.insights[j];
                            if (typeof it === "string") { s.insights[j] = tr(it); }
                            else if (it && typeof it === "object") {
                                if (typeof it.text === "string") { it.text = tr(it.text); }
                                if (typeof it.title === "string") { it.title = tr(it.title); }
                            }
                        }
                    }
                }
            } catch (e) {}
            return s;
        };
    }
    function install(proto) {
        if (!proto || Object.prototype.hasOwnProperty.call(proto, "__eqilGuarded")) { return; }
