        _tr(key, fallback) {
            if (!key) return fallback;
            var sim = window.mySimulation;
            var v = sim && sim.t ? sim.t(key) : null;
            return (v && v !== key) ? v : fallback;
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var n = idx + 1;

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = (window.mySimulation && window.mySimulation.t(round.titleKey)) || round.titleDefault;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = this._tr('round' + n + '_briefing', round.briefing);

            var d1Label = document.getElementById('decision1Label');
            if (d1Label) d1Label.innerHTML = this._tr(round.d1LabelKey, round.d1Label);

            var d2Label = document.getElementById('decision2Label');
            if (d2Label) d2Label.innerHTML = this._tr(round.d2LabelKey, round.d2Label);

            var d2Group = document.getElementById('decision2Group');
            if (d2Group) d2Group.style.display = round.showD2 ? 'block' : 'none';

            var sel1 = document.getElementById('decision1Select');
            if (sel1 && round.options1.length > 0) {
                sel1.innerHTML = '';
                for (var i = 0; i < round.options1.length; i++) {
                    var opt = document.createElement('option');
                    opt.value = round.options1[i].value;
                    opt.textContent = this._tr('round' + n + '_o1_' + round.options1[i].value, round.options1[i].text);
                    sel1.appendChild(opt);
                }
            }

            var sel2 = document.getElementById('decision2Select');
            if (sel2 && round.options2.length > 0) {
                sel2.innerHTML = '';
                for (var j = 0; j < round.options2.length; j++) {
                    var opt2 = document.createElement('option');
                    opt2.value = round.options2[j].value;
                    opt2.textContent = this._tr('round' + n + '_o2_' + round.options2[j].value, round.options2[j].text);
                    sel2.appendChild(opt2);
                }
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new AgenticEnterpriseAdapter(), {
            simulationType: 'agentic_enterprise_060',
            maxPeriods: 5,
            autoSaveInterval: 30000
        });
